#!/usr/bin/env bash
# Writes charts/cloudnative-app/values-dev.yaml from Terraform outputs.
# Usage: bash scripts/gen-values.sh [image-tag]     (default v1)
set -euo pipefail

TAG="${1:-v1}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT/envs/dev"
out() { terraform output -raw "$1"; }

cat > "$ROOT/charts/cloudnative-app/values-dev.yaml" <<YAML
# GENERATED by scripts/gen-values.sh - safe to commit (endpoints and ARNs, no secrets)
api:
  image:
    repository: $(out ecr_api_url)
    tag: $TAG
frontend:
  image:
    repository: $(out ecr_frontend_url)
    tag: $TAG
data:
  dbHost: $(out rds_address)
  dbSecretArn: $(out rds_master_secret_arn)
  redisHost: $(out redis_primary_endpoint)
irsa:
  apiRoleArn: $(out api_role_arn)
YAML

echo "Wrote charts/cloudnative-app/values-dev.yaml"
